// Packet D — route-level combination proof on production scenery, real Rapier.
//
// Every target body is generated by a production path: the Crucible arena's own debris
// field (swarmArena._spawnDebrisRock via run:wavePlanned), the Adventure sector's compact
// asteroid-field records (world.js enterSector, promoted to live bodies by the shared
// adapter or a live effect), and bodies those generators produce in play (environmentMaterials
// crystal-fracture shards). The only hand-placed entities are the player ship, the
// tool/effect entities a case deploys, and one deployed vector mine — per the packet contract.
import assert from 'node:assert/strict';
import test from 'node:test';

import { createSimulation, SIM_DT } from '../src/core/sim.js';
import { createBus } from '../src/core/eventBus.js';
import { physics } from '../src/core/physics.js';
import { world } from '../src/systems/world.js';
import { runSession } from '../src/systems/runSession.js';
import { survivalRun } from '../src/systems/survivalRun.js';
import { swarmArena, SWARM_DEBRIS_TAG } from '../src/systems/swarmArena.js';
import { planWave } from '../src/systems/survivalWavePlanner.js';
import { SWARM_RULESET } from '../src/data/swarmMode.js';
import { weapons, buildWeaponDamagePacket } from '../src/systems/weapons.js';
import { bombs } from '../src/systems/bombs.js';
import { fields } from '../src/systems/fields.js';
import { FIELD_FLAGS, FIELD_DEFS } from '../src/data/fields.js';
import { environmentMaterials, addEnvironmentHeat } from '../src/systems/environmentMaterials.js';
import { dockingCorridor } from '../src/systems/dockingCorridor.js';
import { collisionConsequences } from '../src/systems/collisionConsequences.js';
import { resolveAutopilotTarget } from '../src/systems/flightV3.js';
import { WEAPONS } from '../src/data/weapons.js';
import { ENVIRONMENT_FAMILIES, environmentMaterialOf } from '../src/data/environmentMaterials.js';
import { COMBAT_FLAGS } from '../src/data/featureFlags.js';
import { environmentResponse } from '../src/core/physicalResponse.js';
import {
  schedulePhysicalBlast,
  deliverPhysicalImpulse,
  queryPhysicalBodies,
  resolvePhysicalImpulse,
} from '../src/combat/physicalEffects.js';
import {
  queuePhysicsImpulse,
  writePhysicsControl,
  readExternalPhysicsFeedback,
  resolvePhysicsBodySpec,
} from '../src/core/physicsAuthority.js';
import { readRecentImpulseProvenanceHistory } from '../src/combat/impulseKernel.js';
import {
  proxyWorldPrimitives,
  proxyOuterRadiusWu,
  resolveBerthWorld,
  resolveCollisionProxyManifest,
  resolveCorridorAxisWorld,
} from '../src/data/collisionProxyManifests.js';

const DT = SIM_DT;
const ARENA = 'helios_core';
const SECTOR = 'sector_helios_prime';

function shipSpec(pos, rot = 0) {
  return {
    type: 'ship', team: 0, pos: { x: pos.x, z: pos.z }, radius: 12, mass: 28, collides: true,
    vel: { x: 0, z: 0 }, rot, angVel: 0, hull: 200, hullMax: 200, flightModel: { inertia: 88 },
    flags: {},
    physicsBody: { schemaVersion: 1, radius: 12, mass: 28, inertiaY: 88, dynamic: true, ccd: true, material: 'ship', revision: 0 },
    data: { combatProfileId: 'combat_profile_standard_ship' },
  };
}

const dist = (a, b) => Math.hypot(a.pos.x - b.pos.x, a.pos.z - b.pos.z);
const speed = (e) => Math.hypot(e.vel?.x || 0, e.vel?.z || 0);
const dvel = (a, b) => Math.hypot(a.x - b.x, a.z - b.z);
const unitTo = (from, to) => {
  const dx = to.x - from.x, dz = to.z - from.z;
  const d = Math.hypot(dx, dz) || 1;
  return { x: dx / d, z: dz / d };
};

/** The live generated arena scenery — only what swarmArena's own spawn path produced. */
function arenaDebris(state) {
  return state.entityList.filter((e) => e.alive !== false && e.data && e.data[SWARM_DEBRIS_TAG] === true);
}

/**
 * The production Crucible: runSession + survivalRun own the run record, swarmArena owns the
 * generated debris field, and the full weapon/bomb/material/field delivery stack runs ahead
 * of the real Rapier owner in the same order the production manifest uses.
 */
async function bootArena(seed = 4242, opts = {}) {
  const bus = createBus();
  const sim = createSimulation({
    seed, bus,
    systems: [runSession, survivalRun, swarmArena, weapons, bombs, environmentMaterials, fields, physics],
  });
  const { state } = sim;
  state.mode = 'flight';
  state.input.actions = state.input.actions || {};
  const player = sim.spawn(shipSpec({ x: 0, z: 0 }));
  state.playerId = player.id;
  player.isPlayer = true;
  bus.emit('run:beginRequested', { kind: 'survival', ruleset: SWARM_RULESET, seed, arenaId: ARENA });
  bus.emit('run:wavePlanned', { wave: 1, plan: planWave({ seed, arenaId: ARENA, wave: 1, ruleset: SWARM_RULESET }) });
  // The player's Rapier body is created at prepareBackend with the entity's current yaw, and
  // yaw is body-authoritative afterwards — a cone aim has to be pointed before this call.
  if (opts.aimAtNearestDebris) {
    const nearest = [...arenaDebris(state)].sort((a, b) => dist(a, player) - dist(b, player))[0];
    if (nearest) player.rot = Math.atan2(nearest.pos.z - player.pos.z, nearest.pos.x - player.pos.x);
  }
  const ready = await sim.registry.get('physics').prepareBackend(state);
  assert.equal(ready, true, 'the production Rapier owner boots headless in the arena');
  return { sim, state, bus, player };
}

/** A real Adventure starting sector through the world.js generation path. */
async function bootAdventure(seed = 4242, systems = [world, weapons, environmentMaterials, physics]) {
  const bus = createBus();
  const sim = createSimulation({ seed, bus, systems });
  const { state } = sim;
  state.mode = 'flight';
  state.input.actions = state.input.actions || {};
  const player = sim.spawn(shipSpec({ x: 0, z: 0 }));
  state.playerId = player.id;
  player.isPlayer = true;
  sim.registry.get('world').enterSector(SECTOR);
  const ready = await sim.registry.get('physics').prepareBackend(state);
  assert.equal(ready, true, 'the production Rapier owner boots headless in the sector');
  return { sim, state, bus, player };
}

/** The generated compact asteroid-field records world.js produced for this sector. */
function fieldRecords(state) {
  return (state.world?.asteroidField?.rocks || []).filter((r) => r && r.alive !== false && r.pos);
}

/** Promote a generated compact record through the shared adapter and return its live body. */
function promoteRecord(state, helpers, rec) {
  const out = [];
  queryPhysicalBodies(state, rec.pos, 4, helpers, out);
  const live = rec.liveEntityId != null ? state.entities.get(rec.liveEntityId) : null;
  return live || out.find((e) => e.type === 'asteroid') || null;
}

/**
 * Park the ship inside the generated field — the only hand-placed entity the contract
 * allows — so the promoted scenery lands inside the physics-fidelity region the way it
 * does in ordinary play (effects originate near the player). A small offset keeps the
 * hull clear of the rock it is parked beside.
 */
function parkPlayerAt(player, pos, steps, sim, offset = 60) {
  player.pos.x = pos.x + offset;
  player.pos.z = pos.z;
  player.vel.x = 0;
  player.vel.z = 0;
  for (let i = 0; i < steps; i++) sim.step(DT);
}

/** Count deliveries that route through the real combat-physics port (weapon direct hits). */
function installPortCounter(sim) {
  const calls = [];
  const real = sim.helpers.combatPhysics;
  assert.ok(real && typeof real.applyImpulse === 'function', 'physics installs the combat-physics port');
  sim.helpers.combatPhysics = {
    ...real,
    applyImpulse(input) { calls.push(input); return real.applyImpulse(input); },
  };
  return calls;
}

function weaponDef(id) {
  const def = WEAPONS.find((w) => w.id === id);
  assert.ok(def, `weapon ${id} is a shipped def`);
  return def;
}

/**
 * The real swept-contact seam: the payload physics publishes when a projectile meets a body.
 * The projectile entity and packet are built exactly the way the weapons spawn path builds
 * them; the weapons system's own projectile:hit listener delivers the physical consequence.
 * The round is then retired, the way a connecting hit retires a bolt — otherwise the still-
 * live projectile would legitimately hit the same body again on the next sweep.
 */
function fireAt(state, bus, sim, shooter, defId, target, aimFrom) {
  const def = weaponDef(defId);
  const packet = buildWeaponDamagePacket({ defId: def.id }, def, def.dmg, def.damageType);
  const from = aimFrom || { x: target.pos.x - 240, z: target.pos.z };
  const dir = unitTo(from, target.pos);
  const contact = {
    x: target.pos.x - dir.x * (target.radius || 1),
    z: target.pos.z - dir.z * (target.radius || 1),
  };
  const projectile = sim.spawn({
    type: 'projectile', team: shooter.team, ownerId: shooter.id,
    pos: { ...contact }, vel: { x: dir.x * 320, z: dir.z * 320 },
    radius: 1, mass: 0.1, collides: true,
    data: {
      kind: 'bullet', weaponId: def.id, damagePacket: packet, damage: def.dmg,
      damageType: def.damageType, splashRadius: def.splashRadius || 0, splashDmg: def.splashDmg || 0,
    },
  });
  const payload = {
    projectileId: projectile.id, targetId: target.id, ownerId: shooter.id,
    pos: { ...contact }, damagePacket: packet,
    receipt: { velocity: { x: dir.x * 320, z: dir.z * 320 } },
  };
  bus.emit('projectile:hit', payload);
  projectile.alive = false;
  return { projectile, payload, dir, contact, def, packet };
}

/** The shared blast adapter — the same delivery a hostile detonation uses. */
function blastBeside(state, helpers, center, radius, impulse, evidence = {}) {
  schedulePhysicalBlast(state, {
    center, radius, helpers,
    onBody: (body) => {
      const dx = body.pos.x - center.x, dz = body.pos.z - center.z;
      const d = Math.hypot(dx, dz) || 1;
      deliverPhysicalImpulse(state, body, { x: (dx / d) * impulse, z: (dz / d) * impulse },
        { kind: 'route_test_blast', tick: state.tick, ...evidence });
    },
  });
}

// ─── Crucible route ────────────────────────────────────────────────────────────────

test('crucible route: the generated arena debris field covers all five material families', async () => {
  const t = await bootArena(4242);
  try {
    const rocks = arenaDebris(t.state);
    assert.ok(rocks.length >= 10, `generated arena scenery exists (${rocks.length} bodies)`);
    const mats = new Set(rocks.map(environmentMaterialOf));
    assert.deepEqual([...mats].sort(), [...ENVIRONMENT_FAMILIES].sort(),
      'every material family occurs among generated arena scenery');
  } finally { t.sim.dispose(); }
});

test('crucible route: cone, repulsor, and well move generated debris the authored way', async () => {
  const prevFields = FIELD_FLAGS.enabled;
  FIELD_FLAGS.enabled = true;
  // The ship's nose is set on the nearest generated rock before its Rapier body exists.
  const t = await bootArena(4242, { aimAtNearestDebris: true });
  try {
    const { sim, state, player } = t;

    // Clearing Cone — toggled through the real player-input seam; the wedge follows the
    // ship's body-authoritative heading.
    const rocks = arenaDebris(state);
    const nearest = [...rocks].sort((a, b) => dist(a, player) - dist(b, player))[0];
    const cdir = unitTo(player.pos, nearest.pos);
    const coneStart = { x: nearest.pos.x, z: nearest.pos.z };
    const coneDrift = (nearest.vel?.x || 0) * cdir.x + (nearest.vel?.z || 0) * cdir.z;
    state.input.actions.toggleClearingCone = true;
    for (let i = 0; i < 90; i++) sim.step(DT);
    const coneDisp = (nearest.pos.x - coneStart.x) * cdir.x + (nearest.pos.z - coneStart.z) * cdir.z - coneDrift * 90 * DT;
    assert.ok(coneDisp >= nearest.radius,
      `cone displaces the nearest generated rock by at least its radius (got ${coneDisp.toFixed(2)} of ${nearest.radius.toFixed(2)})`);
    state.input.actions.toggleClearingCone = true; // toggle back off — real edge, real teardown
    sim.step(DT);

    // Repulsor — dropped at the ship inside a generated cluster: every covered rock gets a
    // positive outward radial velocity.
    let group = [];
    for (const a of rocks) {
      const g = rocks.filter((b) => b.alive !== false && dist(a, b) <= FIELD_DEFS.repulsor.radius - 20);
      if (g.length > group.length) group = g;
    }
    assert.ok(group.length >= 3, `a generated cluster of ≥3 rocks exists (${group.length})`);
    const centroid = {
      x: group.reduce((s, r) => s + r.pos.x, 0) / group.length,
      z: group.reduce((s, r) => s + r.pos.z, 0) / group.length,
    };
    player.pos.x = centroid.x; player.pos.z = centroid.z;
    player.vel.x = 0; player.vel.z = 0;
    state.input.actions.deployRepulsor = true;
    for (let i = 0; i < 45; i++) sim.step(DT);
    const pushed = [];
    for (const r of group) {
      if (r.alive === false) continue;
      const dx = r.pos.x - centroid.x, dz = r.pos.z - centroid.z;
      const d = Math.hypot(dx, dz);
      if (d >= FIELD_DEFS.repulsor.radius + r.radius) continue; // already shoved out of the volume
      const radial = d > 1e-4 ? (r.vel.x * dx + r.vel.z * dz) / d : 0;
      assert.ok(radial > 0.05, `repulsor gives each covered generated rock outward velocity (got ${radial.toFixed(2)})`);
      pushed.push(r.id);
    }
    assert.ok(pushed.length >= 3, 'at least three generated rocks took the repulsor shove');

    // Well — aimed near generated rocks: distance to the well shrinks, and once the field is
    // torn down (the real counterplay: its emitter dies) the pulled rocks keep their launch
    // momentum — no residual damping term survives the field.
    const rocks2 = arenaDebris(state).filter((r) => !group.includes(r));
    let pair = null;
    for (const a of rocks2) {
      const near = rocks2.filter((b) => b !== a && dist(a, b) <= 150);
      if (near.length >= 1) { pair = [a, near[0]]; break; }
    }
    if (!pair) pair = rocks2.slice(0, 2);
    assert.ok(pair.length === 2, 'two generated rocks are available for the well pull');
    const mid = {
      x: (pair[0].pos.x + pair[1].pos.x) / 2,
      z: (pair[0].pos.z + pair[1].pos.z) / 2,
    };
    // The emitter lands at the aim point itself. Aim beside the pair — inside the strong
    // part of the radial falloff — so both rocks get pulled in the same direction rather
    // than head-on into each other.
    const pvx = pair[1].pos.x - pair[0].pos.x, pvz = pair[1].pos.z - pair[0].pos.z;
    const plen = Math.hypot(pvx, pvz) || 1;
    const aim = { x: mid.x + (-pvz / plen) * 90, z: mid.z + (pvx / plen) * 90 };
    state.input.aimWorld = aim;
    player.pos.x = aim.x - 200; player.pos.z = aim.z; // inside deployRange 520
    player.vel.x = 0; player.vel.z = 0;
    state.input.actions.deployWell = true;
    sim.step(DT);
    const emitter = state.entityList.find((e) => e.alive !== false && e.data?.fieldKind === 'well');
    assert.ok(emitter, 'the well deploys a real emitter entity');
    const startD = pair.map((r) => Math.hypot(r.pos.x - emitter.pos.x, r.pos.z - emitter.pos.z));
    for (let i = 0; i < 60; i++) sim.step(DT);
    pair.forEach((r, i) => {
      const dNow = Math.hypot(r.pos.x - emitter.pos.x, r.pos.z - emitter.pos.z);
      assert.ok(dNow < startD[i] - 5,
        `well reduces the generated rock's distance to it (${startD[i].toFixed(1)} → ${dNow.toFixed(1)})`);
    });
    // The real counterplay end: a deployed emitter that dies unregisters its field.
    emitter.hull = 0;
    emitter.alive = false;
    sim.step(DT);
    const postEndSpeeds = pair.map(speed);
    for (let i = 0; i < 45; i++) sim.step(DT);
    pair.forEach((r, i) => {
      assert.ok(speed(r) > 0.5,
        `after the well ends the launched rock keeps nonzero momentum (was ${postEndSpeeds[i].toFixed(2)}, now ${speed(r).toFixed(2)})`);
    });
  } finally { FIELD_FLAGS.enabled = prevFields; t.sim.dispose(); }
});

test('crucible route: a concussion round out-throws a pulse round on comparable generated rocks', async () => {
  const prev = COMBAT_FLAGS.weaponImpulseConsequences;
  COMBAT_FLAGS.weaponImpulseConsequences = true;
  const t = await bootArena(4242);
  try {
    const { sim, state, bus, player } = t;
    sim.step(DT);
    // Two comparable generated rocks: nearest pair of debris by radius.
    const rocks = arenaDebris(state);
    let best = null;
    for (let i = 0; i < rocks.length; i++) {
      for (let j = i + 1; j < rocks.length; j++) {
        const d = Math.abs(rocks[i].radius - rocks[j].radius);
        if (!best || d < best.d) best = { a: rocks[i], b: rocks[j], d };
      }
    }
    assert.ok(best, 'two comparable generated rocks exist');
    const beforeA = { x: best.a.vel.x, z: best.a.vel.z };
    const beforeB = { x: best.b.vel.x, z: best.b.vel.z };
    fireAt(state, bus, sim, player, 'wpn_pulse_laser_s', best.a);
    fireAt(state, bus, sim, player, 'wpn_concussion_cannon_m', best.b);
    sim.step(DT);
    const dvPulse = dvel(best.a.vel, beforeA);
    const dvConc = dvel(best.b.vel, beforeB);
    assert.ok(dvPulse > 0.1, `the pulse round moved a generated rock (${dvPulse.toFixed(2)} wu/s)`);
    assert.ok(dvConc > 0.1, `the concussion round moved a generated rock (${dvConc.toFixed(2)} wu/s)`);
    assert.ok(dvConc >= 3 * dvPulse,
      `concussion Δv (${dvConc.toFixed(2)}) ≥ 3× pulse Δv (${dvPulse.toFixed(2)})`);
  } finally { COMBAT_FLAGS.weaponImpulseConsequences = prev; t.sim.dispose(); }
});

test('crucible route: plasma splash delivers exactly once per generated body', async () => {
  const prev = COMBAT_FLAGS.weaponImpulseConsequences;
  COMBAT_FLAGS.weaponImpulseConsequences = true;
  const t = await bootArena(4242);
  try {
    const { sim, state, bus, player } = t;
    sim.step(DT);
    // The arena generates a crystal rock; heating it through the same seam weapons use
    // fractures it into a cluster of generated physical shards — close enough for splash.
    const crystal = arenaDebris(state)
      .filter((r) => environmentMaterialOf(r) === 'crystal')
      .sort((a, b) => a.radius - b.radius)[0];
    assert.ok(crystal, 'the generated arena field carries crystal');
    addEnvironmentHeat(state, crystal, 48, { actorId: player.id });
    sim.step(DT);
    assert.equal(crystal.alive, false, 'the generated crystal fractured');
    const shards = state.entityList.filter((e) => e.alive !== false && e.data?.materialFragment === true);
    assert.ok(shards.length >= 2, `fracture produced generated shards (${shards.length})`);
    sim.step(DT); // let the shards register with the native owner
    // Pick the closest shard pair: A is the direct target, B the splash neighbour.
    let pair = null;
    for (let i = 0; i < shards.length; i++) {
      for (let j = i + 1; j < shards.length; j++) {
        const d = dist(shards[i], shards[j]);
        if (!pair || d < pair.d) pair = { a: shards[i], b: shards[j], d };
      }
    }
    assert.ok(pair, 'two generated shards within splash reach');
    const calls = installPortCounter(sim);
    const beforeA = { x: pair.a.vel.x, z: pair.a.vel.z };
    const beforeB = { x: pair.b.vel.x, z: pair.b.vel.z };
    const tickBefore = state.tick;
    // Fire from B's side so the contact point (splash center) sits on A's face toward B.
    const hit = fireAt(state, bus, sim, player, 'wpn_plasma_cannon_m', pair.a, pair.b.pos);
    // A repeat emit of the same contact must not re-deliver — the contact stamp dedups.
    bus.emit('projectile:hit', { ...hit.payload });
    sim.step(DT);
    // Direct target: exactly one accepted delivery — one port call, one provenance record.
    const history = readRecentImpulseProvenanceHistory(pair.a, state.tick)
      .filter((r) => r.appliedTick >= tickBefore && r.tag === 'plasma_pressure');
    assert.equal(history.length, 1, 'the direct target carries exactly one impulse-provenance record');
    const portForA = calls.filter((c) => c.entityId === pair.a.id);
    assert.equal(portForA.length, 1, 'the port saw exactly one direct delivery to the target');
    const massA = resolvePhysicsBodySpec(pair.a).mass;
    const expectedA = 36 * (massA / 16 * environmentResponse(pair.a)) / massA;
    const dvA = dvel(pair.a.vel, beforeA);
    assert.ok(Math.abs(dvA - expectedA) < Math.max(0.15, expectedA * 0.3),
      `direct Δv ${dvA.toFixed(3)} ≈ a single direct delivery ${expectedA.toFixed(3)} — no splash double-count`);
    // Splash neighbour: exactly one accepted delivery, bounded between none and two.
    const dCenter = Math.hypot(pair.b.pos.x - hit.contact.x, pair.b.pos.z - hit.contact.z);
    const fall = Math.max(0, 1 - Math.max(0, dCenter - (pair.b.radius || 0)) / hit.def.splashRadius);
    assert.ok(fall > 0, `the generated neighbour sits inside the splash (falloff ${fall.toFixed(2)})`);
    const expectedB = 36 * fall * environmentResponse(pair.b) / 16;
    const dvB = dvel(pair.b.vel, beforeB);
    assert.ok(dvB > expectedB * 0.5 && dvB < expectedB * 1.5,
      `splash neighbour Δv ${dvB.toFixed(3)} ≈ exactly one accepted delivery ${expectedB.toFixed(3)}`);
  } finally { COMBAT_FLAGS.weaponImpulseConsequences = prev; t.sim.dispose(); }
});

test('crucible route: a drift bomb and a deployed vector mine each deliver exactly once', async () => {
  const prev = COMBAT_FLAGS.weaponImpulseConsequences;
  const prevFling = COMBAT_FLAGS.tumbleFling;
  COMBAT_FLAGS.weaponImpulseConsequences = true;
  COMBAT_FLAGS.tumbleFling = true; // production profile: the shockwave sweep is part of the blast
  const t = await bootArena(4242);
  try {
    const { sim, state, bus, player } = t;
    sim.step(DT);
    // Densest generated cluster — ship parks at its centroid, the drum drops beside it.
    const rocks = arenaDebris(state);
    let group = [];
    for (const a of rocks) {
      const g = rocks.filter((b) => dist(a, b) <= 150);
      if (g.length > group.length) group = g;
    }
    assert.ok(group.length >= 3, `generated cluster for ordnance coverage (${group.length})`);
    const centroid = {
      x: group.reduce((s, r) => s + r.pos.x, 0) / group.length,
      z: group.reduce((s, r) => s + r.pos.z, 0) / group.length,
    };
    player.pos.x = centroid.x; player.pos.z = centroid.z;
    player.vel.x = 0; player.vel.z = 0; player.rot = Math.PI;
    // The starter rack already carries concussion drums — select it through the live runtime.
    state.bombs = { selectedId: 'bomb_concussion' };
    const detonated = [];
    bus.on('bombs:detonated', (p) => detonated.push(p));
    state.input.actions.dropBomb = true;
    sim.step(DT);
    const bomb = state.entityList.find((e) => e.alive !== false && e.type === 'bomb');
    assert.ok(bomb, 'the drop path produced a drifting bomb entity');
    for (let i = 0; i < 34; i++) sim.step(DT); // arm (0.5 s)
    const calls = installPortCounter(sim);
    state.input.actions.chargeDetonate = true;
    for (let i = 0; i < 20 && detonated.length === 0; i++) sim.step(DT);
    assert.equal(detonated.length, 1, 'the commanded drum detonated once');
    // Every generated rock inside the blast got exactly one blast delivery (a shockwave-sweep
    // pass is a separate authored mechanism and counts separately).
    const recipients = [];
    for (const r of rocks) {
      if (r.alive === false) continue;
      const blastCalls = calls.filter((c) => c.entityId === r.id && c.reason === 'bomb_blast');
      if (blastCalls.length === 0) continue; // outside the falloff — not a recipient
      assert.equal(blastCalls.length, 1, `generated rock ${r.id} received exactly one blast delivery`);
      assert.ok(speed(r) > 0.05, `generated rock ${r.id} moved (${speed(r).toFixed(2)} wu/s)`);
      const sweepCalls = calls.filter((c) => c.entityId === r.id && c.reason === 'shockwave_sweep');
      assert.ok(sweepCalls.length <= 1, 'the sweep pass is itself single-shot per body');
      recipients.push(r.id);
    }
    assert.ok(recipients.length >= 2, `the blast reached generated scenery (${recipients.length} recipients)`);

    // A deployed vector mine — the deployable this case needs, spawned through the real
    // weapons deploy path with the shipped wpn_vector_mine_m definition.
    const mineDef = weaponDef('wpn_vector_mine_m');
    const fresh = arenaDebris(state);
    const mineHits = [];
    bus.on('weapons:mineDetonated', (p) => mineHits.push(p));
    // Deploy amid rocks that were not the bomb's recipients.
    const targets = fresh.filter((r) => r.alive !== false && !recipients.includes(r.id));
    assert.ok(targets.length >= 1, 'generated rocks remain for the mine');
    const anchor = targets[0];
    const weaponsSys = sim.registry.get('weapons');
    // Stand the ship at the anchor rock; the mine drops behind it inside blast radius.
    player.pos.x = anchor.pos.x - 40; player.pos.z = anchor.pos.z;
    player.vel.x = 0; player.vel.z = 0; player.rot = Math.PI; // mine drops +x of the ship → at the rock
    const mine = weaponsSys._spawnVectorMine(player, { defId: mineDef.id }, mineDef, state);
    assert.ok(mine, 'the production deploy path produced the vector mine');
    const minePos = { x: mine.pos.x, z: mine.pos.z };
    const covered = fresh.filter((r) => r.alive !== false
      && Math.hypot(r.pos.x - minePos.x, r.pos.z - minePos.z) - (r.radius || 0) < mine.data.blastRadius);
    assert.ok(covered.length >= 1, 'generated rocks sit inside the mine blast');
    const mineBefore = new Map(covered.map((r) => [r.id, { x: r.vel.x, z: r.vel.z }]));
    weaponsSys._detonateVectorMine(mine, mine.data, state);
    for (let i = 0; i < 3; i++) sim.step(DT);
    assert.equal(mineHits.length, 1, 'the mine detonated exactly once');
    const hitIds = mineHits[0].hits || [];
    for (const r of covered) {
      const count = hitIds.filter((id) => id === r.id).length;
      assert.equal(count, 1, `generated rock ${r.id} took exactly one accepted mine delivery`);
      const dv = dvel(r.vel, mineBefore.get(r.id));
      assert.ok(dv > 0.05, `generated rock ${r.id} moved (${dv.toFixed(2)} wu/s)`);
    }
  } finally { COMBAT_FLAGS.weaponImpulseConsequences = prev; COMBAT_FLAGS.tumbleFling = prevFling; t.sim.dispose(); }
});

test('crucible route: a hostile blast budgets the player but never takes the helm', async () => {
  const t = await bootArena(4242);
  try {
    const { sim, state, player } = t;
    sim.step(DT);
    // The hostile effect source — a hand-placed hostile hull, the tool the case needs.
    const hostile = sim.spawn(shipSpec({ x: player.pos.x + 60, z: player.pos.z }));
    hostile.team = 1;
    blastBeside(state, sim.helpers, { x: player.pos.x + 26, z: player.pos.z }, 90, 1600,
      { actorId: hostile.id, weaponId: 'hostile_blast' });
    sim.step(DT);
    const feedback = readExternalPhysicsFeedback(player);
    assert.ok(feedback, 'the budget recorded the external hit');
    assert.ok(feedback.deltaV <= 5 + 1e-6,
      `hostile blast Δv is capped by the external budget (${feedback.deltaV.toFixed(3)} ≤ 5)`);
    assert.equal(player.angVel || 0, 0, 'no externally induced spin');
    // Helm still answers on the following ticks: thrust along current motion adds speed and
    // the torque channel still turns the hull.
    const v0 = { x: player.vel.x, z: player.vel.z };
    const fdir = unitTo({ x: 0, z: 0 }, v0);
    const rot0 = player.rot;
    for (let i = 0; i < 30; i++) {
      writePhysicsControl(player, {
        mode: 'flight',
        force: { x: fdir.x * 480, y: 0, z: fdir.z * 480 },
        torque: { x: 0, y: 140, z: 0 },
        authority: { forward: 1, reverse: 1, strafe: 1, yaw: 1 },
        maxSpeed: 300,
        source: 'route_helm',
      });
      sim.step(DT);
    }
    const dvAlongThrust = (player.vel.x - v0.x) * fdir.x + (player.vel.z - v0.z) * fdir.z;
    assert.ok(dvAlongThrust > 1,
      `thrust still accelerates the ship (${dvAlongThrust.toFixed(2)} wu/s along the burn)`);
    assert.ok(Math.abs(player.rot - rot0) > 0.01 || Math.abs(player.angVel || 0) > 0.01,
      `steering still turns the ship (rot ${rot0.toFixed(3)} → ${player.rot.toFixed(3)})`);
  } finally { t.sim.dispose(); }
});

