test('adventure route: the generated starting sector carries all five material families', async () => {
  const t = await bootAdventure(4242);
  try {
    const { state } = t;
    const records = fieldRecords(state);
    assert.ok(records.length >= 50, `generated field scenery exists (${records.length} records)`);
    const mats = new Set(records.map(environmentMaterialOf));
    // Wrecks generated into the sector are the debris family.
    for (const e of state.entityList) {
      if (e.alive !== false && (e.type === 'wreck' || e.type === 'asteroid')) mats.add(environmentMaterialOf(e));
    }
    assert.deepEqual([...mats].sort(), [...ENVIRONMENT_FAMILIES].sort(),
      `${SECTOR} field records + generated wrecks cover every material family`);
  } finally { t.sim.dispose(); }
});

test('adventure route: heating generated volatile detonates once and generated crystal fractures into ore shards', async () => {
  const t = await bootAdventure(4242);
  try {
    const { sim, state, bus, player } = t;
    sim.step(DT);
    // A generated volatile record with a dense generated neighbourhood.
    const records = fieldRecords(state);
    let volatileRec = null, volatileNeighbours = [];
    for (const v of records.filter((r) => environmentMaterialOf(r) === 'volatile')) {
      const n = records.filter((o) => o !== v && Math.hypot(o.pos.x - v.pos.x, o.pos.z - v.pos.z) <= 90);
      if (n.length > volatileNeighbours.length) { volatileRec = v; volatileNeighbours = n; }
    }
    assert.ok(volatileRec, 'a generated volatile body exists in the sector field');
    assert.ok(volatileNeighbours.length >= 3, `generated neighbours crowd it (${volatileNeighbours.length})`);
    // Park inside the field: effects originate near the player in ordinary play, which is
    // what brings the promoted scenery into physics fidelity.
    parkPlayerAt(player, volatileRec.pos, 3, sim);
    const detonations = [];
    bus.on('environment:detonated', (p) => detonations.push(p));
    const volatileLive = promoteRecord(state, sim.helpers, volatileRec);
    assert.ok(volatileLive, 'the shared adapter promoted the generated volatile record');
    sim.step(DT); // register the promoted body with the native owner
    assert.ok(addEnvironmentHeat(state, volatileLive, 48, { actorId: player.id }),
      'the weapon heating seam accepted the generated volatile');
    const volatilePos = { x: volatileLive.pos.x, z: volatileLive.pos.z };
    for (let i = 0; i < 20; i++) sim.step(DT);
    assert.equal(volatileLive.alive, false, 'the generated volatile detonated');
    const ownDetonations = detonations.filter((p) => p.id === volatileLive.id);
    assert.equal(ownDetonations.length, 1, 'the volatile detonated exactly once');
    // The material blast promotes + shoves generated neighbours.
    const moved = state.entityList.filter((e) => e.alive !== false
      && e.type === 'asteroid' && e.id !== volatileLive.id
      && Math.hypot(e.pos.x - volatilePos.x, e.pos.z - volatilePos.z) <= 140
      && speed(e) > 0.5);
    assert.ok(moved.length >= 2, `generated neighbours moved (${moved.length} bodies)`);
    // A dead body cannot cook off a second time.
    assert.equal(addEnvironmentHeat(state, volatileLive, 48, { actorId: player.id }), false);
    for (let i = 0; i < 5; i++) sim.step(DT);
    assert.equal(detonations.filter((p) => p.id === volatileLive.id).length, 1,
      're-heating the wreck never fires a second detonation');

    // A generated crystal: same heating seam, fracture path. Park beside it first.
    const crystalRec = fieldRecords(state).find((r) => environmentMaterialOf(r) === 'crystal')
      || null;
    const crystalLiveFromBlast = !crystalRec
      ? state.entityList.find((e) => e.alive !== false && e.type === 'asteroid' && environmentMaterialOf(e) === 'crystal')
      : null;
    assert.ok(crystalRec || crystalLiveFromBlast, 'a generated crystal body exists in the sector field');
    const crystalTarget = crystalRec ? crystalRec.pos : crystalLiveFromBlast.pos;
    parkPlayerAt(player, crystalTarget, 3, sim);
    const fractures = [];
    bus.on('environment:fractured', (p) => fractures.push(p));
    const crystalLive = crystalRec
      ? promoteRecord(state, sim.helpers, crystalRec)
      : crystalLiveFromBlast;
    assert.ok(crystalLive, 'the shared adapter promoted the generated crystal body');
    sim.step(DT);
    const crystalPos = { x: crystalLive.pos.x, z: crystalLive.pos.z };
    assert.ok(addEnvironmentHeat(state, crystalLive, 48, { actorId: player.id }),
      'the weapon heating seam accepted the generated crystal');
    for (let i = 0; i < 10; i++) sim.step(DT);
    assert.equal(crystalLive.alive, false, 'the generated crystal fractured');
    const ownFractures = fractures.filter((p) => p.id === crystalLive.id);
    assert.equal(ownFractures.length, 1, 'the crystal fractured exactly once');
    const shards = state.entityList.filter((e) => e.alive !== false
      && e.data?.materialFragment === true
      && Math.hypot(e.pos.x - crystalPos.x, e.pos.z - crystalPos.z) < 90);
    assert.ok(shards.length >= 4, `fracture produced generated shards (${shards.length})`);
    for (const s of shards) {
      assert.equal(environmentMaterialOf(s), 'crystal', 'each shard keeps the crystal family');
      assert.ok((s.data?.yieldU || 0) > 0, `each shard is ore-bearing (yieldU ${s.data?.yieldU})`);
      assert.ok(s.physicsBody && speed(s) > 0, 'each shard is a live physical body in flight');
    }
  } finally { t.sim.dispose(); }
});

test('adventure route: a missile blast moves generated scenery while the station still docks and blocks', async () => {
  const prev = COMBAT_FLAGS.weaponImpulseConsequences;
  COMBAT_FLAGS.weaponImpulseConsequences = true;
  const t = await bootAdventure(4343, [world, weapons, environmentMaterials, physics, dockingCorridor, collisionConsequences]);
  try {
    const { sim, state, bus, player } = t;
    sim.step(DT);
    // Two generated records close enough that a missile splash reaches the second.
    const records = fieldRecords(state);
    let pair = null;
    for (let i = 0; i < records.length; i++) {
      for (let j = i + 1; j < records.length; j++) {
        const a = records[i], b = records[j];
        const gap = Math.hypot(a.pos.x - b.pos.x, a.pos.z - b.pos.z) - (a.radius || 0) - (b.radius || 0);
        if (gap < 36 && (!pair || gap < pair.gap)) pair = { a, b, gap };
      }
    }
    assert.ok(pair, 'two generated records within missile splash reach');
    parkPlayerAt(player, pair.a.pos, 3, sim);
    const direct = promoteRecord(state, sim.helpers, pair.a);
    assert.ok(direct, 'the shared adapter promoted the direct target');
    sim.step(DT); // register the promoted body so the combat port answers for it
    const calls = installPortCounter(sim);
    const directBefore = { x: direct.vel.x, z: direct.vel.z };
    const hit = fireAt(state, bus, sim, player, 'wpn_missile_rack_m', direct, pair.b.pos);
    for (let i = 0; i < 6; i++) sim.step(DT);
    // Direct target moved and took exactly one delivery through the port.
    const dvDirect = dvel(direct.vel, directBefore);
    assert.ok(dvDirect > 0.1, `the missile moved its generated target (${dvDirect.toFixed(2)} wu/s)`);
    const directCalls = calls.filter((c) => c.entityId === direct.id);
    assert.equal(directCalls.length, 1, 'exactly one direct delivery on the generated target');
    // Generated neighbours: promoted by the splash itself, moved once each.
    const liveNear = state.entityList.filter((e) => e.alive !== false && e.type === 'asteroid'
      && e.id !== direct.id
      && Math.hypot(e.pos.x - hit.contact.x, e.pos.z - hit.contact.z) <= 90
      && speed(e) > 0.1);
    assert.ok(liveNear.length >= 1, `the splash moved generated neighbours (${liveNear.length} bodies)`);

    // Same scenario, same live sim: the generated Helios station still docks…
    const station = state.entityList.find(
      (e) => e.alive && e.type === 'station' && e.data && e.data.stationId === 'station_helios');
    assert.ok(station, 'the generated Helios station exists');
    const manifest = resolveCollisionProxyManifest(station);
    const axis = resolveCorridorAxisWorld(station, manifest);
    const berth = resolveBerthWorld(station, manifest);
    const along = manifest.docking.corridor.mouthRadius * station.data.dockRadius + 30;
    player.pos.x = station.pos.x + axis.x * along;
    player.pos.z = station.pos.z + axis.z * along;
    player.vel.x = -axis.x * 20;
    player.vel.z = -axis.z * 20;
    const autopilot = {
      active: true, targetEntityId: station.id,
      target: { x: station.pos.x, z: station.pos.z },
      label: 'Helios Station', arrivalRadius: station.data.dockRadius,
    };
    let berthed = false;
    for (let i = 0; i < 3600; i++) {
      const target = resolveAutopilotTarget(state, autopilot);
      if (!target) break;
      const ax = target.x - player.pos.x, az = target.z - player.pos.z;
      const d = Math.hypot(ax, az) || 1;
      const spd = Math.hypot(player.vel.x, player.vel.z);
      if (d > target.arrivalRadius && spd < 45) {
        queuePhysicsImpulse(player,
          { x: (ax / d) * 80 * player.mass * DT, y: 0, z: (az / d) * 80 * player.mass * DT });
      } else if (spd > 8) {
        queuePhysicsImpulse(player,
          { x: -player.vel.x * player.mass * 0.05, y: 0, z: -player.vel.z * player.mass * 0.05 });
      }
      sim.step(DT);
      if (state.dockingCorridor && state.dockingCorridor.phase === 'berthed') { berthed = true; break; }
    }
    assert.ok(berthed, 'the corridor berths the ship in the same scenario as the missile blast');

    // …and still blocks a hull driven into its silhouette.
    const primitives = proxyWorldPrimitives(station, manifest);
    const solid = primitives.filter((p) => p.kind === 'circle').sort((a, b) => b.r - a.r)[0];
    assert.ok(solid, 'the compound proxy has a solid face');
    player.pos.x = solid.x + solid.r + player.radius + 70;
    player.pos.z = solid.z;
    player.vel.x = -50; player.vel.z = 0;
    player.flags.docked = false;
    let maxOverlap = 0;
    for (let i = 0; i < 180; i++) {
      sim.step(DT);
      const live = proxyWorldPrimitives(station, manifest);
      for (const p of live) {
        if (p.kind !== 'circle') continue;
        const gap = Math.hypot(player.pos.x - p.x, player.pos.z - p.z) - p.r - player.radius;
        if (-gap > maxOverlap) maxOverlap = -gap;
      }
    }
    const outer = proxyOuterRadiusWu(manifest, station);
    const distCenter = Math.hypot(player.pos.x - station.pos.x, player.pos.z - station.pos.z);
    assert.ok(maxOverlap < 3, `the station hull still blocks (${maxOverlap.toFixed(2)} wu overlap)`);
    assert.ok(distCenter < outer + 400, 'the hull never tunnels through the silhouette');
    assert.equal(player.hull, 200, 'no collision-consequence damage on the player');
  } finally { COMBAT_FLAGS.weaponImpulseConsequences = prev; t.sim.dispose(); }
});
